begin;

create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;

select plan(70);

select ok((select relrowsecurity from pg_class where oid = 'public.profiles'::regclass), 'profiles has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.platform_admins'::regclass), 'platform_admins has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.businesses'::regclass), 'businesses has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.business_members'::regclass), 'business_members has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.business_invitations'::regclass), 'business_invitations has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.categories'::regclass), 'categories has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.feature_definitions'::regclass), 'feature_definitions has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.category_features'::regclass), 'category_features has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.listings'::regclass), 'listings has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.listing_feature_values'::regclass), 'listing_feature_values has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.listing_images'::regclass), 'listing_images has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.leads'::regclass), 'leads has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.favorites'::regclass), 'favorites has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.listing_views'::regclass), 'listing_views has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.audit_logs'::regclass), 'audit_logs has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.lead_rate_limits'::regclass), 'lead_rate_limits has RLS');
select ok((select relrowsecurity from pg_class where oid = 'public.lead_notification_jobs'::regclass), 'lead_notification_jobs has RLS');

select ok(not pg_catalog.has_table_privilege('anon', 'public.leads', 'SELECT'), 'anon cannot read leads');
select ok(not pg_catalog.has_table_privilege('anon', 'public.leads', 'INSERT'), 'anon cannot insert leads directly');
select ok(pg_catalog.has_table_privilege('anon', 'public.listings', 'SELECT'), 'anon may query RLS-filtered listings');
select ok(pg_catalog.has_table_privilege('authenticated', 'public.leads', 'SELECT'), 'authenticated role may query RLS-filtered leads');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.leads', 'UPDATE'), 'authenticated cannot update leads directly');
select ok(not pg_catalog.has_table_privilege('anon', 'public.lead_rate_limits', 'SELECT'), 'anon cannot read lead rate limits');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.lead_notification_jobs', 'SELECT'), 'authenticated cannot read notification jobs');
select ok(not pg_catalog.has_table_privilege('anon', 'public.business_invitations', 'SELECT'), 'anon cannot read business invitations');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.business_invitations', 'SELECT'), 'authenticated cannot read invitations directly');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.business_members', 'INSERT'), 'authenticated cannot insert members directly');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.business_members', 'UPDATE'), 'authenticated cannot update members directly');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.business_members', 'DELETE'), 'authenticated cannot delete members directly');
select ok(pg_catalog.has_function_privilege('anon', 'public.create_public_lead(uuid,text,text,text,date,text,text,text,text,text,text)', 'EXECUTE'), 'anon may call the validated lead RPC');
select ok(not pg_catalog.has_table_privilege('authenticated', 'public.listing_views', 'INSERT'), 'authenticated cannot insert listing views directly');
select ok(pg_catalog.has_function_privilege('anon', 'public.record_listing_view(uuid,text,text)', 'EXECUTE'), 'anon may call the validated view RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.purge_expired_operational_data(integer,integer,integer)', 'EXECUTE'), 'anon cannot execute retention cleanup');
select ok(pg_catalog.has_function_privilege('service_role', 'public.purge_expired_operational_data(integer,integer,integer)', 'EXECUTE'), 'service role may execute retention cleanup');
select ok(not pg_catalog.has_function_privilege('anon', 'public.review_listing(uuid,text,text)', 'EXECUTE'), 'anon cannot review listings');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.review_listing(uuid,text,text)', 'EXECUTE'), 'authenticated may enter the admin-checked review RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.update_business_lead_status(uuid,public.lead_status)', 'EXECUTE'), 'anon cannot update lead status');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.update_business_lead_status(uuid,public.lead_status)', 'EXECUTE'), 'authenticated may enter the membership-checked lead status RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.get_business_analytics(uuid,integer)', 'EXECUTE'), 'anon cannot read business analytics');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.get_business_analytics(uuid,integer)', 'EXECUTE'), 'authenticated may enter the membership-checked analytics RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.claim_lead_notification_jobs(integer,uuid)', 'EXECUTE'), 'anon cannot claim notification jobs');
select ok(not pg_catalog.has_function_privilege('authenticated', 'public.claim_lead_notification_jobs(integer,uuid)', 'EXECUTE'), 'authenticated cannot claim notification jobs');
select ok(pg_catalog.has_function_privilege('service_role', 'public.claim_lead_notification_jobs(integer,uuid)', 'EXECUTE'), 'service role may claim notification jobs');
select ok(not pg_catalog.has_function_privilege('authenticated', 'public.purge_expired_operational_data(integer,integer,integer)', 'EXECUTE'), 'authenticated cannot execute retention cleanup');
select ok(not pg_catalog.has_function_privilege('anon', 'public.submit_listing_for_review(uuid,uuid)', 'EXECUTE'), 'anon cannot submit listings for review');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.submit_listing_for_review(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the membership-checked submission RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.reopen_listing_for_editing(uuid,uuid)', 'EXECUTE'), 'anon cannot reopen reviewed listings');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.reopen_listing_for_editing(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the membership-checked reopen RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.reorder_listing_images(uuid,uuid[])', 'EXECUTE'), 'anon cannot reorder listing images');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.reorder_listing_images(uuid,uuid[])', 'EXECUTE'), 'authenticated may enter the membership-checked image reorder RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.set_listing_image_cover(uuid,uuid)', 'EXECUTE'), 'anon cannot select listing covers');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.set_listing_image_cover(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the membership-checked cover RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.delete_listing_image(uuid,uuid)', 'EXECUTE'), 'anon cannot delete listing image metadata');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.delete_listing_image(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the membership-checked image deletion RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.get_business_members(uuid)', 'EXECUTE'), 'anon cannot list business members');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.get_business_members(uuid)', 'EXECUTE'), 'authenticated may enter the membership-checked member list RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.get_business_invitations(uuid)', 'EXECUTE'), 'anon cannot list business invitations');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.get_business_invitations(uuid)', 'EXECUTE'), 'authenticated may enter the owner-checked invitation list RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.create_business_invitation(uuid,text,public.business_role,text)', 'EXECUTE'), 'anon cannot create business invitations');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.create_business_invitation(uuid,text,public.business_role,text)', 'EXECUTE'), 'authenticated may enter the owner-checked invitation RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.get_business_invitation_preview(text)', 'EXECUTE'), 'anon cannot preview business invitations');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.get_business_invitation_preview(text)', 'EXECUTE'), 'authenticated may preview an email-matched invitation');
select ok(not pg_catalog.has_function_privilege('anon', 'public.accept_business_invitation(text)', 'EXECUTE'), 'anon cannot accept business invitations');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.accept_business_invitation(text)', 'EXECUTE'), 'authenticated may accept an email-matched invitation');
select ok(not pg_catalog.has_function_privilege('anon', 'public.update_business_member_role(uuid,uuid,public.business_role)', 'EXECUTE'), 'anon cannot change business roles');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.update_business_member_role(uuid,uuid,public.business_role)', 'EXECUTE'), 'authenticated may enter the owner-checked role RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.remove_business_member(uuid,uuid)', 'EXECUTE'), 'anon cannot remove business members');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.remove_business_member(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the owner-checked member removal RPC');
select ok(not pg_catalog.has_function_privilege('anon', 'public.revoke_business_invitation(uuid,uuid)', 'EXECUTE'), 'anon cannot revoke business invitations');
select ok(pg_catalog.has_function_privilege('authenticated', 'public.revoke_business_invitation(uuid,uuid)', 'EXECUTE'), 'authenticated may enter the owner-checked invitation revoke RPC');

select * from finish();
rollback;
